//! Source-backed FCH ACPIMMIO and always-on device power control.
// tock's generated byte-register alignment assertions take remainder by one.
#![allow(clippy::modulo_one)]
use crate::ACPI_MMIO;
use tock_registers::{
    LocalRegisterCopy,
    interfaces::{ReadWriteable, Readable, Writeable},
    register_bitfields, register_structs,
    registers::{ReadOnly, ReadWrite},
};
pub mod early;
#[cfg(feature = "smi")]
pub mod smi;

register_bitfields![u8,
    /// AOAC device D3 control (ACPIMMIO 0x1e40 + 2 * device).
    pub AoacControl [TARGET OFFSET(0) NUMBITS(2) [Initialized=1], POWER OFFSET(3) NUMBITS(1) []],
    pub AoacState [POWER_RESET OFFSET(0) NUMBITS(1) [], REFERENCE_CLOCK OFFSET(1) NUMBITS(1) []],
    /// PMx74.
    pub AcpiConfig [DECODE_STD OFFSET(0) NUMBITS(1) [], GLOBAL_EN OFFSET(1) NUMBITS(1) [],
        RTC_EN_EN OFFSET(2) NUMBITS(1) [], TIMER_EN_EN OFFSET(4) NUMBITS(1) []],
    /// PMx75: PMx74[15:8].
    pub AcpiConfigHigh [PWRBTN_EN OFFSET(0) NUMBITS(1) []],
    /// PMxBE.
    pub ResetControl1 [KB_RESET_EN OFFSET(4) NUMBITS(1) [], SLP_TYPE_EN OFFSET(5) NUMBITS(1) []]
];
register_bitfields![u32,
    /// PMx00 decode enables.
    pub Decode [LEGACY OFFSET(0) NUMBITS(1) [], CF9 OFFSET(1) NUMBITS(1) [],
        DMA OFFSET(2) NUMBITS(1) [], DMA80 OFFSET(3) NUMBITS(1) [],
        SMBUS_ASF_IO OFFSET(4) NUMBITS(1) [],
        IOAPIC OFFSET(5) NUMBITS(1) [], HPET OFFSET(6) NUMBITS(1) [],
        SMBUS_ASF_IO_BASE OFFSET(8) NUMBITS(8) [],
        HPET64 OFFSET(28) NUMBITS(1) [], HPET_MSI OFFSET(29) NUMBITS(1) []],
    /// PMx08.
    pub PciControl [FORCE_STPCLK_RETRY OFFSET(24) NUMBITS(1) [],
        FORCE_SLPSTATE_RETRY OFFSET(25) NUMBITS(1) []]
];
/// The ACPI fixed I/O blocks the FCH decodes (PMx60..PMx68).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AcpiPorts {
    pub event: u16,
    pub control: u16,
    pub timer: u16,
    pub gpe: u16,
}
register_structs! {
    pub(crate) Pm {
        (0x00 => decode: ReadWrite<u32, Decode::Register>),
        (0x04 => _reserved0),
        (0x08 => pub(crate) pci_control: ReadWrite<u32, PciControl::Register>),
        (0x0c => _reserved4),
        (0x60 => event: ReadWrite<u16>),
        (0x62 => control: ReadWrite<u16>),
        (0x64 => timer: ReadWrite<u16>),
        (0x66 => _reserved1),
        (0x68 => gpe: ReadWrite<u16>),
        (0x6a => pub(crate) command: ReadWrite<u16>),
        (0x6c => _reserved2),
        (0x74 => config: ReadWrite<u8, AcpiConfig::Register>),
        (0x75 => pub(crate) config_high: ReadWrite<u8, AcpiConfigHigh::Register>),
        (0x76 => _reserved3),
        (0xbe => pub(crate) reset_control: ReadWrite<u8, ResetControl1::Register>),
        (0xbf => @END),
    },
    AoacDevice {
        (0 => control: ReadWrite<u8, AoacControl::Register>),
        (1 => state: ReadOnly<u8, AoacState::Register>),
        (2 => @END),
    }
}
#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidDevice,
    PowerTimeout(u8),
    Unavailable(u8),
}
pub trait AoacAccess {
    fn control(&mut self, device: u8) -> u8;
    fn set_control(&mut self, device: u8, value: u8);
    fn state(&mut self, device: u8) -> u8;
}
fn valid_device(device: u8) -> bool {
    matches!(device, 0 | 7..=9 | 11..=12 | 16..=17 | 26..=28)
}
/// Validate all devices/controls before power writes. Start every device before
/// waiting; all-ones is unavailable, not a proof that power/clock are ready.
/// After any programming error the caller must stop/reset, not retry.
pub fn power_devices(
    io: &mut impl AoacAccess,
    devices: &[u8],
    polls: u32,
    mut delay_100us: impl FnMut(),
) -> Result<(), Error> {
    if devices.iter().any(|&id| !valid_device(id)) {
        return Err(Error::InvalidDevice);
    }
    let mut controls = [0; 29];
    for &id in devices {
        let control = io.control(id);
        if control == u8::MAX {
            return Err(Error::Unavailable(id));
        }
        controls[usize::from(id)] = control;
    }
    for &id in devices {
        let mut control =
            LocalRegisterCopy::<u8, AoacControl::Register>::new(controls[usize::from(id)]);
        control.modify(AoacControl::POWER::SET + AoacControl::TARGET::Initialized);
        io.set_control(id, control.get());
    }
    for &id in devices {
        let mut remaining = polls;
        loop {
            let state = io.state(id);
            if state == u8::MAX {
                return Err(Error::Unavailable(id));
            }
            if LocalRegisterCopy::<u8, AoacState::Register>::new(state)
                .matches_all(AoacState::POWER_RESET::SET + AoacState::REFERENCE_CLOCK::SET)
            {
                break;
            }
            if remaining == 0 {
                return Err(Error::PowerTimeout(id));
            }
            delay_100us();
            remaining -= 1;
        }
    }
    Ok(())
}

/// The PM registers in ACPI MMIO. Callers own them as [`Fch::new`] says.
pub(crate) fn pm() -> &'static Pm {
    // SAFETY: a fixed, always-decoded MMIO block once ACPI MMIO is enabled.
    unsafe { &*((ACPI_MMIO + 0x300) as *const Pm) }
}

pub struct Fch {
    _exclusive: core::marker::PhantomData<*mut ()>,
}
impl Fch {
    /// # Safety
    /// ACPIMMIO is decoded and UC-mapped, no concurrent FCH programming.
    pub unsafe fn new() -> Self {
        Self {
            _exclusive: core::marker::PhantomData,
        }
    }
    fn pm(&self) -> &Pm {
        pm()
    }
    fn device(&self, device: u8) -> Result<&AoacDevice, Error> {
        if !valid_device(device) {
            return Err(Error::InvalidDevice);
        }
        Ok(unsafe { &*((ACPI_MMIO + 0x1e40 + usize::from(device) * 2) as *const AoacDevice) })
    }
    /// Start all devices before waiting. Polling is bounded;
    /// the caller supplies a real 100-us delay, not a CPU-speed-dependent spin.
    pub fn power_devices(
        &mut self,
        devices: &[u8],
        polls: u32,
        delay_100us: impl FnMut(),
    ) -> Result<(), Error> {
        power_devices(self, devices, polls, delay_100us)
    }
    pub fn clear_legacy_uart_decode(&mut self) {
        // Range_0 defaults enabled. No legacy aliases for the MMIO UART.
        unsafe { &*(0xfedc0020 as *const ReadWrite<u16>) }.set(0);
    }
    pub fn enable_legacy_decode(&mut self) {
        self.pm()
            .decode
            .modify(Decode::LEGACY::SET + Decode::CF9::SET);
    }
    pub fn disable_legacy_dma(&mut self) {
        self.pm()
            .decode
            .modify(Decode::DMA::CLEAR + Decode::DMA80::CLEAR);
    }
    pub fn enable_hpet_ioapic(&mut self) {
        self.pm().decode.modify(
            Decode::IOAPIC::SET + Decode::HPET::SET + Decode::HPET_MSI::SET + Decode::HPET64::CLEAR,
        );
    }
    /// fch_init_acpi_decode: the ACPI blocks and their standard decode.
    pub fn acpi_decode(&mut self, ports: AcpiPorts) {
        let pm = self.pm();
        pm.event.set(ports.event);
        pm.control.set(ports.control);
        pm.timer.set(ports.timer);
        pm.gpe.set(ports.gpe);
        pm.config.modify(AcpiConfig::DECODE_STD::SET);
    }
    /// fch_init_acpi_ports without an SMI handler: no SMI command port, so no
    /// SMI routing is enabled.
    pub fn acpi_ports_without_smm(&mut self, ports: AcpiPorts) {
        self.acpi_decode(ports);
        let pm = self.pm();
        pm.command.set(0);
        pm.config.write(
            AcpiConfig::DECODE_STD::SET
                + AcpiConfig::GLOBAL_EN::SET
                + AcpiConfig::RTC_EN_EN::SET
                + AcpiConfig::TIMER_EN_EN::SET,
        );
    }
    pub fn disable_keyboard_reset(&mut self) {
        self.pm()
            .reset_control
            .modify(ResetControl1::KB_RESET_EN::CLEAR);
    }
}

impl AoacAccess for Fch {
    fn control(&mut self, device: u8) -> u8 {
        self.device(device)
            .expect("invalid AOAC device")
            .control
            .get()
    }
    fn set_control(&mut self, device: u8, value: u8) {
        self.device(device)
            .expect("invalid AOAC device")
            .control
            .set(value);
    }
    fn state(&mut self, device: u8) -> u8 {
        self.device(device)
            .expect("invalid AOAC device")
            .state
            .get()
    }
}
